import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [h, w] = lines[0].split(" ").map(Number);

// s[i][j] = 左上 (1,1) から右下 (i,j) までの長方形の和
const s: number[][] = Array.from({ length: h + 1 }, () => new Array(w + 1).fill(0));
for (let i = 1; i <= h; i++) {
  const row = lines[i].split(" ").map(Number);
  for (let j = 1; j <= w; j++) {
    s[i][j] = row[j - 1] + s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1];
  }
}

const q = Number(lines[h + 1]);
const out: number[] = [];
for (let k = 0; k < q; k++) {
  const [a, b, c, d] = lines[h + 2 + k].split(" ").map(Number);
  out.push(s[c][d] - s[a - 1][d] - s[c][b - 1] + s[a - 1][b - 1]);
}
console.log(out.join("\n"));
